// ============ Bottom Nav ============
// ============ Setores (alertas agrupados por setor, item pedido: aba separada) ============
const ICONE_SETOR = {
  "Hortifruti": Carrot,
  "Açougue": Beef,
  "Padaria": Croissant,
  "Frios e Laticínios": Milk,
  "Mercearia": ShoppingBasket,
  "Bebidas": Wine,
  "Congelados": Snowflake,
  "Limpeza": SprayCan,
  "Higiene e Perfumaria": Sparkles,
  "Bazar": Boxes,
  "CPD / Depósito": Warehouse
};
function iconeDoSetor(nome) { return ICONE_SETOR[nome] || Package; }

function isSameDay(isoA, isoB) {
  if (!isoA || !isoB) return false;
  const a = new Date(isoA), b = new Date(isoB);
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}
function tempoDesde(dataISO) {
  if (!dataISO) return "nunca conferido";
  const ms = Date.now() - new Date(dataISO).getTime();
  const horas = Math.floor(ms / 3600000);
  if (horas < 1) return `há ${Math.max(1, Math.floor(ms / 60000))}min`;
  if (horas < 24) return `há ${horas}h`;
  return `há ${Math.floor(horas / 24)}d`;
}
function SetoresView({ T, items, catalog, rondas, onIniciarRonda, onOpenDetail, onLancarValidade, onAbrirSetor }) {
  const enriched = items.map((it) => ({ ...it, status: getStatus(it) }));
  const barcodesComItemAtivo = new Set(items.map((it) => it.barcode));

  const ultimaRondaPorSetor = useMemo(() => {
    const mapa = {};
    rondas.forEach((r) => { if (!mapa[r.setor] || new Date(r.finalizadoEm) > new Date(mapa[r.setor])) mapa[r.setor] = r.finalizadoEm; });
    return mapa;
  }, [rondas]);

  const grupos = useMemo(() => {
    const mapa = {};
    enriched.forEach((i) => {
      if (!mapa[i.setor]) mapa[i.setor] = { total: 0, alerta: 0, vencido: 0, semValidadeCount: 0, valor: 0, itens: [] };
      mapa[i.setor].total++;
      if (i.status.level === "alert") mapa[i.setor].alerta++;
      if (i.status.level === "expired") mapa[i.setor].vencido++;
      if (i.status.level === "alert" || i.status.level === "expired") mapa[i.setor].valor += (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0);
      mapa[i.setor].itens.push(i);
    });
    // Produtos cadastrados no catálogo mas ainda sem nenhuma validade lançada: aparecem também, não ficam escondidos
    Object.entries(catalog || {}).forEach(([barcode, dados]) => {
      if (barcodesComItemAtivo.has(barcode) || !dados.setor) return;
      if (!mapa[dados.setor]) mapa[dados.setor] = { total: 0, alerta: 0, vencido: 0, semValidadeCount: 0, valor: 0, itens: [] };
      mapa[dados.setor].total++;
      mapa[dados.setor].semValidadeCount++;
      mapa[dados.setor].itens.push({ id: `catalogo-${barcode}`, barcode, semValidade: true, ...dados });
    });
    return Object.entries(mapa).sort((a, b) => (b[1].vencido * 2 + b[1].alerta) - (a[1].vencido * 2 + a[1].alerta));
  }, [enriched, catalog]);

  const resumo = useMemo(() => {
    let criticos = 0, atencao = 0, controlados = 0;
    grupos.forEach(([setor, dados]) => {
      const ultimaRonda = ultimaRondaPorSetor[setor];
      const rondaAtrasada = !ultimaRonda || Date.now() - new Date(ultimaRonda).getTime() > 24 * 3600000;
      if (dados.vencido > 0) criticos++;
      else if (dados.alerta > 0 || rondaAtrasada) atencao++;
      else controlados++;
    });
    return { criticos, atencao, controlados };
  }, [grupos, ultimaRondaPorSetor]);

  if (grupos.length === 0) {
    return (
      <div className="px-4 pt-4">
        <div className="text-center py-14 px-6">
          <div style={{ background: BLUE_SOFT }} className="h-16 w-16 rounded-2xl mx-auto flex items-center justify-center mb-3"><LayoutGrid size={26} color={BLUE} /></div>
          <p className="font-semibold text-sm">Nenhum setor com produtos ainda</p>
          <p style={{ color: T.subtext }} className="text-xs mt-1">Assim que você bipar produtos, eles aparecem agrupados aqui.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="px-4 pt-4">
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}
        style={{ background: `linear-gradient(135deg, ${BLUE} 0%, ${BLUE_DARK} 100%)` }} className="rounded-[28px] p-4 mb-4 shadow-lg shadow-black/5">
        <p className="text-white/70 text-[10px] font-semibold uppercase tracking-wide mb-2.5 flex items-center gap-1.5">
          <Squares2X2IconSolid className="w-3.5 h-3.5" /> Visão geral dos setores
        </p>
        <div className="grid grid-cols-3 gap-2">
          <div className="bg-white/10 rounded-2xl px-2 py-2.5 text-center">
            <p className="text-white text-xl font-extrabold leading-none">{resumo.criticos}</p>
            <p className="text-white/70 text-[9px] font-semibold mt-1 uppercase tracking-wide">Críticos</p>
          </div>
          <div className="bg-white/10 rounded-2xl px-2 py-2.5 text-center">
            <p className="text-white text-xl font-extrabold leading-none">{resumo.atencao}</p>
            <p className="text-white/70 text-[9px] font-semibold mt-1 uppercase tracking-wide">Atenção</p>
          </div>
          <div className="bg-white/10 rounded-2xl px-2 py-2.5 text-center">
            <p className="text-white text-xl font-extrabold leading-none">{resumo.controlados}</p>
            <p className="text-white/70 text-[9px] font-semibold mt-1 uppercase tracking-wide">Em dia</p>
          </div>
        </div>
      </motion.div>

      <div className="grid grid-cols-3 gap-2.5">
        {grupos.map(([setor, dados], idx) => {
          const ultimaRonda = ultimaRondaPorSetor[setor];
          const rondaAtrasada = !ultimaRonda || Date.now() - new Date(ultimaRonda).getTime() > 24 * 3600000;
          // Bolinha de status do setor: vermelho (crítico) > laranja (atenção ou ronda atrasada) > verde (controlado)
          let corBolinha, bgIcone, corIcone;
          if (dados.vencido > 0) { corBolinha = RED_DARK; bgIcone = RED_SOFT; corIcone = RED_DARK; }
          else if (dados.alerta > 0 || rondaAtrasada) { corBolinha = "#E0921C"; bgIcone = "#FCF0DD"; corIcone = "#C2760C"; }
          else { corBolinha = "#1F9D55"; bgIcone = "#E4F7EC"; corIcone = "#1F9D55"; }
          const Icone = iconeDoSetor(setor);

          return (
            <motion.button key={setor} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25, delay: Math.min(idx * 0.03, 0.3) }}
              whileTap={{ scale: 0.97 }} onClick={() => onAbrirSetor(setor)} style={{ background: T.card }}
              className="rounded-2xl shadow-lg shadow-black/5 text-left overflow-hidden">
              <div className="p-3 flex flex-col items-center text-center gap-1.5 relative">
                <span style={{ background: corBolinha }} className="absolute top-2 right-2 h-2.5 w-2.5 rounded-full shrink-0" />
                <div style={{ background: bgIcone }} className="h-10 w-10 rounded-xl flex items-center justify-center shrink-0">
                  <Icone size={18} color={corIcone} />
                </div>
                <p className="font-bold text-[11px] leading-tight line-clamp-2 min-h-[26px]">{setor}</p>
                <p style={{ color: T.subtext }} className="text-[9.5px] leading-tight">{dados.total} produto{dados.total !== 1 ? "s" : ""}</p>
              </div>
            </motion.button>
          );
        })}
      </div>
    </div>
  );
}

// Bottom sheet de exclusão reutilizável (mesma lógica de motivo usada no modal de detalhe),
// pra permitir excluir direto da listagem de um setor sem precisar abrir o detalhe do produto.
function ExcluirProdutoSheet({ T, item, onCancel, onConfirmar }) {
  const [motivo, setMotivo] = useState(null);
  const [motivoOutro, setMotivoOutro] = useState("");
  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      <div onClick={onCancel} className="absolute inset-0 bg-black/60" />
      <div style={{ background: T.card }} className="relative w-full max-w-md rounded-t-2xl p-5 pb-7">
        <div className="flex items-center gap-2.5 mb-3">
          <div style={{ background: RED_SOFT }} className="h-10 w-10 rounded-2xl flex items-center justify-center shrink-0"><Trash2 size={18} color={RED_DARK} /></div>
          <div className="min-w-0">
            <h3 className="font-bold text-sm">Excluir produto</h3>
            <p style={{ color: T.subtext }} className="text-xs truncate">{item.nome}</p>
          </div>
        </div>
        <p style={{ color: T.subtext }} className="text-[11px] font-medium mb-2">Excluir sem registrar no histórico. Qual o motivo?</p>
        <div className="grid grid-cols-2 gap-1.5">
          {MOTIVOS_EXCLUSAO.map((m) => (
            <button key={m} onClick={() => setMotivo(m)}
              style={motivo === m ? { background: RED_DARK, color: "#fff" } : { background: T.chipBg, color: T.text }}
              className="text-[11px] font-medium py-2.5 rounded-xl">
              {m}
            </button>
          ))}
        </div>
        {motivo === "Outro" && (
          <input value={motivoOutro} onChange={(e) => setMotivoOutro(e.target.value.slice(0, 80))}
            placeholder="Descreva o motivo..." autoFocus
            style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }}
            className="w-full min-w-0 mt-2 border rounded-xl px-3 py-2 text-xs outline-none focus:ring-2" />
        )}
        <div className="flex gap-2 mt-3">
          <button onClick={onCancel} style={{ color: T.subtext }} className="flex-1 text-xs py-2.5">Cancelar</button>
          <button
            onClick={() => onConfirmar(motivo === "Outro" ? (motivoOutro.trim() || "Outro") : motivo)}
            disabled={!motivo || (motivo === "Outro" && !motivoOutro.trim())}
            style={{ background: RED_DARK, color: "#fff" }} className="flex-[2] text-sm font-semibold py-2.5 rounded-xl disabled:opacity-40">
            Sim, excluir
          </button>
        </div>
      </div>
    </div>
  );
}

// ============ Página de detalhe de um setor (com filtros e "+" pra cadastrar naquele setor) ============
// Card individual (grid 2 colunas) usado na listagem do setor — extraído pra ser reaproveitado
// tanto pra itens únicos quanto dentro do agrupamento por produto.
function ItemCardGridSetor({ T, item, onOpenDetail, onLancarValidade, onExcluir, setItemParaExcluir }) {
  return (
    <div style={{ background: T.card, borderColor: T.border, borderStyle: item.semValidade ? "dashed" : "solid" }}
      className="relative rounded-2xl overflow-hidden border shadow-lg shadow-black/5 text-left">
      <button onClick={() => (item.semValidade ? onLancarValidade(item) : onOpenDetail(item))} className="block w-full text-left">
        <div className="relative">
          {item.foto ? <img src={item.foto} alt="" className="w-full h-24 object-cover" /> : (
            <div style={{ background: BLUE_SOFT }} className="w-full h-24 flex items-center justify-center"><Package size={24} color={BLUE} /></div>
          )}
          {!item.semValidade && (
            <span style={{ background: statusStyles(item.status.level).bg, color: statusStyles(item.status.level).fg }} className="absolute top-1.5 left-1.5 text-[9px] font-bold px-1.5 py-0.5 rounded">
              {item.status.label}
            </span>
          )}
          {item.semValidade && (
            <span style={{ background: "rgba(11,79,158,0.85)", color: "#fff" }} className="absolute top-1.5 left-1.5 h-5 w-5 rounded-full flex items-center justify-center">
              <Plus size={12} />
            </span>
          )}
          {!item.semValidade && item.local === "deposito" && (
            <span style={{ background: "rgba(0,0,0,0.6)", color: "#fff" }} className="absolute top-1.5 right-1.5 text-[8px] font-bold px-1.5 py-0.5 rounded">DEP</span>
          )}
        </div>
        <div className="p-2.5 pr-8">
          <p className="font-semibold text-xs truncate">{item.nome}</p>
          <p style={{ color: T.subtext }} className="text-[10px] mt-1">{item.semValidade ? "Toque pra cadastrar" : formatarData(item.validade)}</p>
        </div>
      </button>
      {!item.semValidade && onExcluir && (
        <button onClick={() => setItemParaExcluir(item)} style={{ background: "rgba(0,0,0,0.45)" }}
          className="absolute bottom-2 right-2 h-6 w-6 rounded-full flex items-center justify-center">
          <Trash2 size={12} color="#fff" />
        </button>
      )}
    </div>
  );
}

// Card agrupado (grid 2 colunas) — mesmo produto com datas e/ou locais diferentes.
// Expande ocupando as 2 colunas pra mostrar o detalhe de cada lote.
function ItemCardGridAgrupado({ T, base, lotes, totalQuantidade, piorStatus, onOpenDetail }) {
  const [aberto, setAberto] = useState(false);
  const s = statusStyles(piorStatus.level);
  const temDeposito = lotes.some((l) => l.local === "deposito");
  const temLoja = lotes.some((l) => (l.local || "loja") === "loja");

  return (
    <div style={{ background: T.card, borderColor: T.border, gridColumn: aberto ? "1 / -1" : undefined }}
      className="relative rounded-2xl overflow-hidden border shadow-lg shadow-black/5 text-left">
      <button onClick={() => setAberto((v) => !v)} className="block w-full text-left">
        <div className="relative">
          {base.foto ? <img src={base.foto} alt="" className="w-full h-24 object-cover" /> : (
            <div style={{ background: BLUE_SOFT }} className="w-full h-24 flex items-center justify-center"><Package size={24} color={BLUE} /></div>
          )}
          <span style={{ background: s.bg, color: s.fg }} className="absolute top-1.5 left-1.5 text-[9px] font-bold px-1.5 py-0.5 rounded">{piorStatus.label}</span>
          <span style={{ background: "rgba(11,79,158,0.85)", color: "#fff" }} className="absolute top-1.5 right-1.5 text-[8px] font-bold px-1.5 py-0.5 rounded">{lotes.length}x datas</span>
        </div>
        <div className="p-2.5">
          <p className="font-semibold text-xs truncate">{base.nome}</p>
          <p style={{ color: T.subtext }} className="text-[10px] mt-1">{totalQuantidade} un no total{temDeposito && temLoja ? " · Loja + Depósito" : ""}</p>
        </div>
      </button>
      {aberto && (
        <div style={{ borderColor: T.border }} className="border-t px-2.5 py-2 flex flex-col gap-1.5">
          {lotes.map((l) => {
            const sl = statusStyles(l.status.level);
            return (
              <button key={l.id} onClick={() => onOpenDetail(l)} style={{ background: T.chipBg }} className="w-full text-left rounded-xl p-2 flex items-center justify-between gap-2">
                <div className="min-w-0 flex items-center gap-1.5">
                  <span style={{ background: sl.bg, color: sl.fg }} className="text-[9px] font-bold px-1.5 py-0.5 rounded shrink-0">{sl.label}</span>
                  <span className="text-xs font-semibold">{formatarData(l.validade)}</span>
                  <span style={{ color: T.subtext }} className="text-[10px]">· {l.quantidade || 1}un</span>
                  {l.local === "deposito" && <span style={{ background: "#EEF0F3", color: "#4B5563" }} className="text-[9px] font-bold px-1.5 py-0.5 rounded shrink-0">DEP</span>}
                </div>
                <ChevronRight size={13} color={T.subtext} className="shrink-0" />
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

function SetorDetalheView({ T, setor, items, catalog, rondas, onVoltar, onIniciarRonda, onRetomarRonda, onOpenDetail, onLancarValidade, onCadastrarNoSetor, onExcluir, usuario, ehEncarregado, designacoesHoje, onDesignarRonda }) {
  const [itemParaExcluir, setItemParaExcluir] = useState(null);
  const [search, setSearch] = useState("");
  const [statusFiltro, setStatusFiltro] = useState("todos"); // todos | alerta | vencido
  const [subsetorFiltro, setSubsetorFiltro] = useState("todos");
  const [ordenarPor, setOrdenarPor] = useState("urgencia"); // urgencia | nome | valor
  const [designarAberto, setDesignarAberto] = useState(false);
  const [nomeDesignado, setNomeDesignado] = useState("");
  const [confirmarInicioRonda, setConfirmarInicioRonda] = useState(false);
  const barcodesComItemAtivo = new Set(items.filter((i) => i.setor === setor).map((it) => it.barcode));

  const itensDoSetor = useMemo(() => {
    const ativos = items.filter((i) => i.setor === setor).map((i) => ({ ...i, status: getStatus(i) }));
    const semValidade = Object.entries(catalog || {})
      .filter(([barcode, dados]) => dados.setor === setor && !barcodesComItemAtivo.has(barcode))
      .map(([barcode, dados]) => ({ id: `catalogo-${barcode}`, barcode, semValidade: true, ...dados }));
    return [...ativos, ...semValidade];
  }, [items, catalog, setor]);

  const subsetoresDisponiveis = useMemo(() => {
    const set = new Set(itensDoSetor.filter((i) => i.subsetor).map((i) => i.subsetor));
    return Array.from(set).sort();
  }, [itensDoSetor]);

  const rondasDoSetor = useMemo(() => rondas.filter((r) => r.setor === setor), [rondas, setor]);
  const ultimaRonda = useMemo(() => {
    const finalizadas = rondasDoSetor.filter((r) => r.finalizadoEm).sort((a, b) => new Date(b.finalizadoEm) - new Date(a.finalizadoEm));
    return finalizadas.length ? finalizadas[0].finalizadoEm : null;
  }, [rondasDoSetor]);

  const hoje = new Date().toISOString();
  const rondasHoje = rondasDoSetor.filter((r) => isSameDay(r.iniciadoEm, hoje));
  const parcialHoje = rondasHoje.find((r) => r.status === "parcial");
  const concluidaHoje = rondasHoje.find((r) => r.status === "concluida");
  const designacaoParaMim = (designacoesHoje || []).find((d) => d.setor === setor && d.usuarioDesignado === usuario);
  // Bloqueia nova ronda só se já teve uma CONCLUÍDA hoje nesse setor — libera de novo se o encarregado designar pra alguém
  const rondaBloqueada = !!concluidaHoje && !designacaoParaMim && !ehEncarregado;

  let filtrados = itensDoSetor.filter((i) => {
    const matchBusca = i.nome.toLowerCase().includes(search.toLowerCase()) || i.barcode.includes(search);
    if (!matchBusca) return false;
    if (subsetorFiltro !== "todos" && i.subsetor !== subsetorFiltro) return false;
    if (i.semValidade) return statusFiltro === "todos";
    if (statusFiltro === "alerta") return i.status.level === "alert";
    if (statusFiltro === "vencido") return i.status.level === "expired";
    return true;
  });
  filtrados = filtrados.sort((a, b) => {
    if (a.semValidade && !b.semValidade) return 1;
    if (!a.semValidade && b.semValidade) return -1;
    if (a.semValidade && b.semValidade) return a.nome.localeCompare(b.nome);
    if (ordenarPor === "nome") return a.nome.localeCompare(b.nome);
    if (ordenarPor === "valor") {
      const valorA = (Number(a.quantidade) || 1) * (Number(a.precoUnitario) || 0);
      const valorB = (Number(b.quantidade) || 1) * (Number(b.precoUnitario) || 0);
      return valorB - valorA;
    }
    return a.status.d - b.status.d;
  });

  const contagens = {
    vencido: itensDoSetor.filter((i) => !i.semValidade && i.status.level === "expired").length,
    alerta: itensDoSetor.filter((i) => !i.semValidade && i.status.level === "alert").length
  };

  return (
    <div className="px-4 pt-4">
      <button onClick={onVoltar} style={{ color: BLUE }} className="flex items-center gap-1.5 text-sm font-medium mb-3">
        <ArrowLeft size={16} /> Todos os setores
      </button>

      <div style={{ background: `linear-gradient(135deg, ${BLUE} 0%, ${BLUE_DARK} 100%)` }} className="rounded-[28px] p-4 mb-4 shadow-lg shadow-black/5">
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            {(() => { const IconeSetor = iconeDoSetor(setor); return (
              <div className="h-9 w-9 rounded-2xl bg-white/15 flex items-center justify-center shrink-0"><IconeSetor size={18} color="#fff" /></div>
            ); })()}
            <h2 className="font-bold text-lg text-white">{setor}</h2>
          </div>
          <button onClick={() => onCadastrarNoSetor(setor)} style={{ background: "rgba(255,255,255,0.2)" }} className="h-9 w-9 rounded-full flex items-center justify-center shrink-0">
            <Plus size={18} color="#fff" />
          </button>
        </div>
        <div className="grid grid-cols-2 gap-2">
          <div className="bg-white/10 rounded-2xl py-2.5 text-center">
            <p className="text-white text-lg font-extrabold leading-none">{contagens.vencido}</p>
            <p className="text-white/70 text-[9px] mt-1">Vencidos</p>
          </div>
          <div className="bg-white/10 rounded-2xl py-2.5 text-center">
            <p className="text-white text-lg font-extrabold leading-none">{contagens.alerta}</p>
            <p className="text-white/70 text-[9px] mt-1">Em alerta</p>
          </div>
        </div>
      </div>

      {/* Informativo de ronda + valor em risco do setor — inclui status de hoje (parcial/concluída/quem fez) */}
      {(() => {
        const valorEmRisco = itensDoSetor.filter((i) => !i.semValidade && (i.status.level === "expired" || i.status.level === "alert"))
          .reduce((acc, i) => acc + (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0), 0);
        const rondaAtrasada = !ultimaRonda || Date.now() - new Date(ultimaRonda).getTime() > 24 * 3600000;
        return (
          <div style={{ background: T.card }} className="rounded-2xl p-3.5 mb-4 shadow-lg shadow-black/5">
            <div className="flex items-center justify-between gap-3">
              <div className="flex items-center gap-2 min-w-0">
                <SignalIcon className="w-4 h-4 shrink-0" style={{ color: rondaAtrasada ? "#C2760C" : "#1F9D55" }} />
                <div className="min-w-0">
                  <p style={{ color: T.subtext }} className="text-[9.5px] font-semibold uppercase tracking-wide">Última ronda</p>
                  <p style={{ color: rondaAtrasada ? "#C2760C" : T.text }} className="text-xs font-bold truncate">{tempoDesde(ultimaRonda)}</p>
                </div>
              </div>
              {valorEmRisco > 0 && (
                <div className="text-right shrink-0">
                  <p style={{ color: T.subtext }} className="text-[9.5px] font-semibold uppercase tracking-wide">Valor em risco</p>
                  <p style={{ color: RED_DARK }} className="text-xs font-extrabold">{formatarMoeda(valorEmRisco)}</p>
                </div>
              )}
            </div>
            {parcialHoje && (
              <p style={{ color: "#C2760C", borderColor: T.border }} className="text-[10.5px] font-semibold mt-2 pt-2 border-t">
                Ronda parcial hoje — iniciada por {parcialHoje.usuario || "alguém"}{parcialHoje.finalizadoPor && parcialHoje.finalizadoPor !== parcialHoje.usuario ? `, retomada por ${parcialHoje.finalizadoPor}` : ""}.
              </p>
            )}
            {concluidaHoje && !parcialHoje && (
              <p style={{ color: "#1F9D55", borderColor: T.border }} className="text-[10.5px] font-semibold mt-2 pt-2 border-t">
                Ronda concluída hoje por {concluidaHoje.finalizadoPor || concluidaHoje.usuario || "alguém"}.
              </p>
            )}
          </div>
        );
      })()}

      {itensDoSetor.some((i) => !i.semValidade) && (
        <>
          {parcialHoje ? (
            <button onClick={() => onRetomarRonda(parcialHoje)} style={{ background: "#FCF0DD", color: "#C2760C" }}
              className="w-full flex items-center justify-center gap-1.5 text-sm font-semibold py-3 rounded-2xl mb-4">
              <ShieldCheck size={16} /> Continuar ronda de hoje (parcial)
            </button>
          ) : rondaBloqueada ? (
            <div style={{ background: T.chipBg }} className="rounded-2xl p-3.5 mb-4">
              <p style={{ color: T.text }} className="text-xs font-semibold mb-1">Ronda já concluída hoje neste setor</p>
              <p style={{ color: T.subtext }} className="text-[11px] mb-2">Só um encarregado pode liberar uma nova ronda hoje pra um funcionário específico.</p>
            </div>
          ) : (
            <button onClick={() => setConfirmarInicioRonda(true)} style={{ background: BLUE_SOFT, color: BLUE_DARK }}
              className="w-full flex items-center justify-center gap-1.5 text-sm font-semibold py-3 rounded-2xl mb-4">
              <ShieldCheck size={16} /> Iniciar ronda deste setor
            </button>
          )}
          {ehEncarregado && concluidaHoje && !parcialHoje && (
            <button onClick={() => setDesignarAberto(true)} style={{ color: BLUE }} className="w-full text-xs font-semibold -mt-2.5 mb-4 flex items-center justify-center gap-1.5">
              <Users2 size={13} /> Designar nova ronda pra um funcionário hoje
            </button>
          )}
        </>
      )}

      <div className="relative mb-3">
        <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2" color={T.subtext} />
        <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Buscar produto ou código..."
          style={{ background: T.card, color: T.text, borderColor: T.inputBorder }}
          className="w-full rounded-2xl pl-9 pr-3 py-2.5 text-sm border outline-none focus:ring-2" />
      </div>

      <div className="flex gap-1.5 overflow-x-auto pb-1 mb-3 no-scrollbar">
        {[["todos", "Todos"], ["vencido", "Vencidos"], ["alerta", "Em alerta"]].map(([id, label]) => (
          <button key={id} onClick={() => setStatusFiltro(id)}
            style={statusFiltro === id ? { background: BLUE, color: "#fff" } : { background: T.chipBg, color: T.text }}
            className="whitespace-nowrap text-[11px] font-medium px-3 py-1.5 rounded-full shrink-0">
            {label}
          </button>
        ))}
        {subsetoresDisponiveis.length > 0 && (
          <select value={subsetorFiltro} onChange={(e) => setSubsetorFiltro(e.target.value)}
            style={{ background: subsetorFiltro !== "todos" ? BLUE : T.chipBg, color: subsetorFiltro !== "todos" ? "#fff" : T.text }}
            className="whitespace-nowrap text-[11px] font-medium px-3 py-1.5 rounded-full shrink-0 outline-none">
            <option value="todos">Todos os subsetores</option>
            {subsetoresDisponiveis.map((s) => <option key={s} value={s}>{s}</option>)}
          </select>
        )}
        <select value={ordenarPor} onChange={(e) => setOrdenarPor(e.target.value)}
          style={{ background: T.chipBg, color: T.text }} className="whitespace-nowrap text-[11px] font-medium pl-2.5 pr-2 py-1.5 rounded-full shrink-0 outline-none flex items-center gap-1">
          <option value="urgencia">Urgência</option>
          <option value="nome">Nome</option>
          <option value="valor">Maior valor</option>
        </select>
      </div>

      {filtrados.length === 0 ? (
        <p style={{ color: T.subtext }} className="text-xs text-center py-8">Nenhum produto encontrado com esse filtro.</p>
      ) : (
        <div className="grid grid-cols-2 gap-2.5">
          {agruparItensPorProduto(filtrados.filter((i) => !i.semValidade)).map((g, i) =>
            g.unico ? (
              <ItemCardGridSetor key={g.item.id} item={g.item} T={T} onOpenDetail={onOpenDetail} onLancarValidade={onLancarValidade} onExcluir={onExcluir} setItemParaExcluir={setItemParaExcluir} />
            ) : (
              <ItemCardGridAgrupado key={`grupo-${i}`} T={T} base={g.base} lotes={g.lotes} totalQuantidade={g.totalQuantidade} piorStatus={g.piorStatus} onOpenDetail={onOpenDetail} />
            )
          )}
          {filtrados.filter((i) => i.semValidade).map((item) => (
            <ItemCardGridSetor key={item.id} item={item} T={T} onOpenDetail={onOpenDetail} onLancarValidade={onLancarValidade} onExcluir={onExcluir} setItemParaExcluir={setItemParaExcluir} />
          ))}
        </div>
      )}

      {itemParaExcluir && (
        <ExcluirProdutoSheet T={T} item={itemParaExcluir} onCancel={() => setItemParaExcluir(null)}
          onConfirmar={(motivo) => { onExcluir(itemParaExcluir, motivo); setItemParaExcluir(null); }} />
      )}

      {/* Confirmação antes de iniciar a ronda */}
      <AnimatePresence>
        {confirmarInicioRonda && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[60] bg-black/50 flex items-end sm:items-center justify-center p-4">
            <motion.div initial={{ y: 30, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 20, opacity: 0 }}
              style={{ background: T.card }} className="w-full max-w-sm rounded-[26px] p-5">
              <div style={{ background: BLUE_SOFT }} className="h-12 w-12 rounded-2xl flex items-center justify-center mb-3">
                <ShieldCheck size={22} style={{ color: BLUE }} />
              </div>
              <h3 className="font-bold text-base mb-1.5">Iniciar ronda em {setor}?</h3>
              <p style={{ color: T.subtext }} className="text-xs mb-5">
                Você vai conferir {itensDoSetor.filter((i) => !i.semValidade).length} produto(s) desse setor, um por um. Pode pausar e retomar depois se precisar.
              </p>
              <div className="flex gap-2">
                <button onClick={() => setConfirmarInicioRonda(false)} style={{ color: T.subtext, borderColor: T.border }} className="flex-1 text-sm font-medium py-3 rounded-2xl border">
                  Cancelar
                </button>
                <button onClick={() => { setConfirmarInicioRonda(false); onIniciarRonda(setor, itensDoSetor.filter((i) => !i.semValidade)); }}
                  style={{ background: BLUE }} className="flex-1 text-sm font-semibold py-3 rounded-2xl text-white">
                  Iniciar ronda
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Encarregado libera uma nova ronda hoje pra um funcionário específico */}
      <AnimatePresence>
        {designarAberto && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[60] bg-black/50 flex items-end sm:items-center justify-center p-4">
            <motion.div initial={{ y: 30, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 20, opacity: 0 }}
              style={{ background: T.card }} className="w-full max-w-sm rounded-[26px] p-5">
              <h3 className="font-bold text-base mb-1.5">Designar nova ronda</h3>
              <p style={{ color: T.subtext }} className="text-xs mb-3">Setor <strong>{setor}</strong> já teve ronda concluída hoje. Informe pra quem liberar uma nova.</p>
              <input autoFocus value={nomeDesignado} onChange={(e) => setNomeDesignado(e.target.value)} placeholder="Nome do funcionário"
                style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2.5 text-sm outline-none focus:ring-2 mb-4" />
              <div className="flex gap-2">
                <button onClick={() => { setDesignarAberto(false); setNomeDesignado(""); }} style={{ color: T.subtext, borderColor: T.border }} className="flex-1 text-sm font-medium py-3 rounded-2xl border">
                  Cancelar
                </button>
                <button disabled={!nomeDesignado.trim()} onClick={() => { onDesignarRonda(setor, nomeDesignado.trim()); setDesignarAberto(false); setNomeDesignado(""); }}
                  style={{ background: nomeDesignado.trim() ? BLUE : "#C7CEDA" }} className="flex-1 text-sm font-semibold py-3 rounded-2xl text-white">
                  Liberar ronda
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

// ============ Ronda de validade (item 44) ============
function RondaView({ T, ronda, onMarcar, onConcluir, onCancelar, onFinalizar, onRenomear, confirmarParcial, onFecharConfirmacao, onAtualizarValidade }) {
  const verificados = ronda.itens.filter((x) => x.statusRonda).length;
  const progresso = ronda.itens.length ? Math.round((verificados / ronda.itens.length) * 100) : 0;
  const [editandoTitulo, setEditandoTitulo] = useState(false);
  const [itemExpandido, setItemExpandido] = useState(null);
  const [rascunhoValidade, setRascunhoValidade] = useState("");
  const [rascunhoAcao, setRascunhoAcao] = useState("");
  const ACOES = ["Redução de preço", "Remanejamento", "Retirar do estoque", "Aguardar troca com fornecedor", "Outro"];
  const OPCOES = [
    { valor: "ok", label: "OK", emoji: "🟢", cor: "#1F9D55", bg: "#E6F7ED" },
    { valor: "proximo", label: "Próximo", emoji: "🟡", cor: "#C2760C", bg: "#FCF0DD" },
    { valor: "vencido", label: "Vencido", emoji: "🔴", cor: RED_DARK, bg: RED_SOFT },
    { valor: "nao_encontrado", label: "Não achei", emoji: "⚫", cor: "#4B5563", bg: "#EEF0F3" }
  ];
  const hojeISO = new Date().toISOString().slice(0, 10);
  const amanhaISO = new Date(Date.now() + 86400000).toISOString().slice(0, 10);

  function abrirEditor(x) {
    setItemExpandido(x.item.id);
    setRascunhoValidade(x.item.validade || "");
    setRascunhoAcao(x.acao || "");
  }
  function marcarComEditor(item, valor) {
    onMarcar(item.id, valor);
    if (valor === "vencido" || valor === "proximo") abrirEditor({ item, acao: "" });
    else if (itemExpandido === item.id) setItemExpandido(null);
  }
  function salvarEditor(itemId) {
    if (rascunhoValidade) onAtualizarValidade(itemId, rascunhoValidade, rascunhoAcao || null);
    setItemExpandido(null);
  }

  if (ronda.resultado) {
    const r = ronda.resultado;
    const parcial = ronda.statusFinal === "parcial";
    return (
      <div className="fixed inset-0 z-50 flex flex-col items-center justify-center px-6" style={{ background: T.bg }}>
        <div style={{ background: parcial ? "#E0921C" : "#1F9D55" }} className="h-16 w-16 rounded-full flex items-center justify-center mb-4">
          {parcial ? <ExclamationTriangleIcon className="w-7 h-7 text-white" /> : <Check size={30} color="#fff" />}
        </div>
        <h2 className="font-bold text-lg text-center">{ronda.titulo || `Ronda de ${ronda.setor}`} {parcial ? "concluída parcialmente" : "concluída"}</h2>
        <p style={{ color: T.subtext }} className="text-xs text-center mt-1 mb-6">
          {parcial ? `${verificados} de ${ronda.itens.length} produto(s) verificados` : `${ronda.itens.length} produto(s) verificados`}
        </p>
        <div className="grid grid-cols-2 gap-2.5 w-full max-w-xs mb-8">
          <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl border p-3 text-center">
            <p className="text-xl font-extrabold">🟢 {r.ok}</p><p style={{ color: T.subtext }} className="text-[10px]">OK</p>
          </div>
          <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl border p-3 text-center">
            <p className="text-xl font-extrabold">🟡 {r.proximo}</p><p style={{ color: T.subtext }} className="text-[10px]">Próximos</p>
          </div>
          <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl border p-3 text-center">
            <p className="text-xl font-extrabold">🔴 {r.vencido}</p><p style={{ color: T.subtext }} className="text-[10px]">Vencidos</p>
          </div>
          <div style={{ background: T.card, borderColor: T.border }} className="rounded-2xl border p-3 text-center">
            <p className="text-xl font-extrabold">⚫ {r.nao_encontrado}</p><p style={{ color: T.subtext }} className="text-[10px]">Não achados</p>
          </div>
        </div>
        <button onClick={onFinalizar} style={{ background: BLUE, color: "#fff" }} className="w-full max-w-xs py-3.5 rounded-2xl text-sm font-semibold">Voltar aos setores</button>
      </div>
    );
  }

  const pendentes = ronda.itens.filter((x) => !x.statusRonda);
  const marcados = ronda.itens.filter((x) => x.statusRonda);

  return (
    <div className="fixed inset-0 z-50 flex flex-col" style={{ background: T.bg }}>
      <div style={{ background: `linear-gradient(135deg, ${BLUE} 0%, ${BLUE_DARK} 100%)` }} className="px-4 pb-4 shrink-0 pt-[calc(env(safe-area-inset-top)+20px)]">
        <div className="flex items-center justify-between mb-3">
          <div className="min-w-0 flex-1">
            <p className="text-white/70 text-[11px] font-medium">RONDA EM ANDAMENTO · {ronda.setor}</p>
            {editandoTitulo ? (
              <input autoFocus value={ronda.titulo || ""} onChange={(e) => onRenomear && onRenomear(e.target.value)}
                onBlur={() => setEditandoTitulo(false)} onKeyDown={(e) => e.key === "Enter" && setEditandoTitulo(false)}
                className="bg-white/15 text-white font-bold text-lg rounded-lg px-2 py-0.5 -ml-2 w-full outline-none" />
            ) : (
              <button onClick={() => onRenomear && setEditandoTitulo(true)} className="text-left">
                <h2 className="text-white font-bold text-lg truncate">{ronda.titulo || `Verificação de Validade — ${ronda.setor}`}</h2>
              </button>
            )}
          </div>
          <button onClick={onCancelar} className="h-9 w-9 rounded-full bg-white/15 flex items-center justify-center shrink-0 ml-2"><CloseIcon size={16} color="#fff" /></button>
        </div>
        <div className="bg-white/15 rounded-full h-2.5 overflow-hidden">
          <div style={{ width: `${progresso}%`, background: "#fff" }} className="h-full rounded-full transition-all" />
        </div>
        <div className="flex items-center justify-between mt-1.5">
          <p className="text-white/80 text-[11px]">{verificados} de {ronda.itens.length} verificados ({progresso}%)</p>
          {pendentes.length > 0 && (
            <button onClick={() => pendentes.forEach((x) => onMarcar(x.item.id, "ok"))} className="text-white text-[11px] font-semibold underline">
              Marcar restantes como OK
            </button>
          )}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-3 flex flex-col gap-2.5 pb-24">
        {[...pendentes, ...marcados].map((x) => {
          const { item, statusRonda, acao } = x;
          const expandido = itemExpandido === item.id;
          const opSelecionada = OPCOES.find((o) => o.valor === statusRonda);
          return (
            <div key={item.id} style={{ background: T.card, borderColor: opSelecionada ? opSelecionada.cor : T.border, borderWidth: opSelecionada ? 1.5 : 1 }}
              className="rounded-2xl overflow-hidden border shadow-lg shadow-black/5 transition-colors">
              <button onClick={() => (expandido ? setItemExpandido(null) : abrirEditor(x))} className="flex items-center gap-3 w-full text-left p-3">
                <div className="relative shrink-0">
                  <Thumb foto={item.foto} size={46} />
                  {opSelecionada && (
                    <span style={{ background: opSelecionada.cor }} className="absolute -bottom-1 -right-1 h-4 w-4 rounded-full flex items-center justify-center text-[9px] shadow">
                      {opSelecionada.emoji}
                    </span>
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold truncate">{item.nome}</p>
                  <p style={{ color: T.subtext }} className="text-[11px] mt-0.5">Validade {formatarData(item.validade)}</p>
                  {acao && <p style={{ color: "#C2760C" }} className="text-[10px] font-semibold mt-0.5">Ação: {acao}</p>}
                </div>
                {opSelecionada ? (
                  <span style={{ background: opSelecionada.bg, color: opSelecionada.cor }} className="text-[9.5px] font-bold px-2 py-1 rounded-full shrink-0">{opSelecionada.label}</span>
                ) : (
                  <ChevronRight size={16} style={{ color: T.subtext }} className="shrink-0" />
                )}
              </button>
              <div style={{ borderColor: T.border }} className="grid grid-cols-4 gap-1.5 px-3 pb-3 border-t pt-2.5">
                {OPCOES.map((o) => {
                  const selecionado = statusRonda === o.valor;
                  return (
                    <button key={o.valor} onClick={() => marcarComEditor(item, o.valor)}
                      style={selecionado ? { background: o.cor, color: "#fff", borderColor: o.cor } : { background: T.chipBg, color: T.text, borderColor: "transparent" }}
                      className="text-[10px] font-semibold py-2 rounded-xl flex flex-col items-center gap-0.5 border transition-colors">
                      <span className="text-sm leading-none">{o.emoji}</span>{o.label}
                    </button>
                  );
                })}
              </div>
              {expandido && (
                <div style={{ borderColor: T.border, background: T.chipBg }} className="px-3 py-3 border-t flex flex-col gap-2">
                  <div>
                    <label style={{ color: T.subtext }} className="text-[10px] font-semibold mb-1 block">Lançar/corrigir validade</label>
                    <input type="date" value={rascunhoValidade} onChange={(e) => setRascunhoValidade(e.target.value)}
                      max={statusRonda === "vencido" ? hojeISO : undefined} min={statusRonda === "proximo" ? amanhaISO : undefined}
                      style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2 text-sm outline-none" />
                    {statusRonda === "vencido" && <p style={{ color: T.subtext }} className="text-[10px] mt-1">Só datas até hoje.</p>}
                    {statusRonda === "proximo" && <p style={{ color: T.subtext }} className="text-[10px] mt-1">Só datas a partir de amanhã.</p>}
                  </div>
                  {(statusRonda === "vencido" || statusRonda === "proximo") && (
                    <div>
                      <label style={{ color: T.subtext }} className="text-[10px] font-semibold mb-1 block">Ação</label>
                      <select value={rascunhoAcao} onChange={(e) => setRascunhoAcao(e.target.value)}
                        style={{ background: T.inputBg, color: T.text, borderColor: T.inputBorder }} className="w-full border rounded-xl px-3 py-2 text-sm outline-none">
                        <option value="">Selecionar ação</option>
                        {ACOES.map((a) => <option key={a} value={a}>{a}</option>)}
                      </select>
                    </div>
                  )}
                  <button onClick={() => salvarEditor(item.id)} disabled={!rascunhoValidade} style={{ background: rascunhoValidade ? BLUE : "#C7CEDA" }}
                    className="w-full text-white text-xs font-semibold py-2.5 rounded-xl">Salvar</button>
                </div>
              )}
            </div>
          );
        })}
      </div>

      <div style={{ background: T.card, borderColor: T.border }} className="border-t p-4 shrink-0">
        <button onClick={() => onConcluir(false)} disabled={verificados === 0}
          style={{ background: verificados > 0 ? BLUE : "#C7CEDA" }} className="w-full text-white text-sm font-semibold py-3.5 rounded-2xl flex items-center justify-center gap-2">
          <Check size={16} /> Concluir ronda
        </button>
      </div>

      <AnimatePresence>
        {confirmarParcial && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[60] bg-black/50 flex items-end sm:items-center justify-center p-4">
            <motion.div initial={{ y: 30, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 20, opacity: 0 }}
              style={{ background: T.card }} className="w-full max-w-sm rounded-[26px] p-5">
              <div style={{ background: "#FCF0DD" }} className="h-12 w-12 rounded-2xl flex items-center justify-center mb-3">
                <ExclamationTriangleIcon className="w-6 h-6" style={{ color: "#C2760C" }} />
              </div>
              <h3 className="font-bold text-base mb-1.5">Nem todos os itens foram conferidos</h3>
              <p style={{ color: T.subtext }} className="text-xs mb-5">
                Faltam {ronda.itens.length - verificados} de {ronda.itens.length} produto(s). Se concluir agora, a ronda ficará registrada como <strong>parcial</strong>. Deseja continuar mesmo assim?
              </p>
              <div className="flex gap-2">
                <button onClick={onFecharConfirmacao} style={{ color: T.subtext, borderColor: T.border }} className="flex-1 text-sm font-medium py-3 rounded-2xl border">
                  Voltar e conferir
                </button>
                <button onClick={() => onConcluir(true)} style={{ background: "#E0921C" }} className="flex-1 text-sm font-semibold py-3 rounded-2xl text-white">
                  Concluir parcial
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

// ============ Rondas (aba própria: Minhas Rondas / Todas as Rondas) ============
function RondasView({ T, rondas, usuario, lojaNumero, onIniciarRonda, onRetomarRonda, items, catalog }) {
  const [subaba, setSubaba] = useState("minhas"); // minhas | todas
  const [rondaSelecionada, setRondaSelecionada] = useState(null);
  const [itensRonda, setItensRonda] = useState(null);
  const [carregandoItens, setCarregandoItens] = useState(false);
  const [filtroDetalhe, setFiltroDetalhe] = useState("conferidos"); // conferidos | pendentes | todos

  const lista = useMemo(() => {
    const base = subaba === "minhas" ? rondas.filter((r) => r.usuario === usuario || r.finalizadoPor === usuario) : rondas;
    return [...base].sort((a, b) => new Date(b.iniciadoEm || b.finalizadoEm) - new Date(a.iniciadoEm || a.finalizadoEm));
  }, [rondas, subaba, usuario]);

  const STATUS_STYLE = {
    concluida: { bg: "#E6F7ED", color: "#1F9D55", label: "Concluída" },
    parcial: { bg: "#FCF0DD", color: "#C2760C", label: "Parcial" },
    em_andamento: { bg: "#FEF3E0", color: "#C98A0C", label: "Em andamento" },
    pendente: { bg: "#EAF1FB", color: BLUE, label: "Pendente" },
  };

  async function abrirRonda(r) {
    setRondaSelecionada(r);
    setCarregandoItens(true);
    setFiltroDetalhe("conferidos");
    const itens = await supaFetchRondaItens(r.id);
    setItensRonda(itens);
    setCarregandoItens(false);
  }

  const TAG_STATUS = {
    ok: { label: "OK", bg: "#1F9D55" },
    proximo: { label: "Próximo", bg: "#C98A0C" },
    vencido: { label: "Vencido", bg: "#A81419" },
    nao_encontrado: { label: "Não achado", bg: "#4B5563" },
  };

  return (
    <div className="px-4 pt-4 pb-4">
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}
        style={{ background: `linear-gradient(160deg, ${BLUE_DARK} 0%, ${BLUE} 75%)` }} className="rounded-[28px] p-4 shadow-lg shadow-black/5 mb-4">
        <p className="text-white/70 text-[10px] font-semibold uppercase tracking-wide flex items-center gap-1.5 mb-2">
          <ClockIconSolid className="w-3.5 h-3.5" /> Rondas · Loja {lojaNumero || "—"}
        </p>
        <div className="grid grid-cols-3 divide-x divide-white/15">
          <div className="text-center">
            <p className="text-white text-lg font-extrabold leading-none">{rondas.length}</p>
            <p className="text-white/60 text-[10px] mt-1">Total</p>
          </div>
          <div className="text-center">
            <p className="text-white text-lg font-extrabold leading-none">{rondas.filter((r) => r.status === "concluida").length}</p>
            <p className="text-white/60 text-[10px] mt-1">Concluídas</p>
          </div>
          <div className="text-center">
            <p className="text-white text-lg font-extrabold leading-none">{rondas.filter((r) => r.status === "parcial").length}</p>
            <p className="text-white/60 text-[10px] mt-1">Parciais</p>
          </div>
        </div>
      </motion.div>

      <div style={{ background: T.chipBg }} className="flex rounded-2xl p-1 mb-4">
        <button onClick={() => setSubaba("minhas")} style={subaba === "minhas" ? { background: T.card, color: RED_DARK } : { color: T.subtext }}
          className="flex-1 text-xs font-semibold py-2 rounded-xl transition">Minhas Rondas</button>
        <button onClick={() => setSubaba("todas")} style={subaba === "todas" ? { background: T.card, color: RED_DARK } : { color: T.subtext }}
          className="flex-1 text-xs font-semibold py-2 rounded-xl transition">Todas as Rondas</button>
      </div>

      {lista.length === 0 ? (
        <div className="text-center py-14 px-6">
          <div style={{ background: BLUE_SOFT }} className="h-16 w-16 rounded-2xl mx-auto flex items-center justify-center mb-3"><ClockIcon className="w-6 h-6" style={{ color: BLUE }} /></div>
          <p className="font-semibold text-sm">Nenhuma ronda registrada</p>
          <p style={{ color: T.subtext }} className="text-xs mt-1">{subaba === "minhas" ? "As rondas que você fizer aparecem aqui." : "As rondas da loja aparecem aqui conforme forem feitas."}</p>
        </div>
      ) : (
        <div className="flex flex-col gap-2.5">
          {lista.map((r) => {
            const st = STATUS_STYLE[r.status] || STATUS_STYLE.concluida;
            const Icone = iconeDoSetor(r.setor);
            const totalConferido = (r.okCount ?? 0) + (r.proximoCount ?? 0) + (r.vencidoCount ?? 0) + (r.naoEncontradoCount ?? 0);
            const pctConferido = r.totalVerificado ? Math.round((totalConferido / r.totalVerificado) * 100) : 0;
            return (
              <motion.button key={r.id} whileTap={{ scale: 0.985 }} onClick={() => abrirRonda(r)} style={{ background: T.card }}
                className="rounded-2xl shadow-lg shadow-black/5 text-left w-full overflow-hidden">
                <div style={{ background: st.color }} className="h-1 w-full" />
                <div className="p-3.5">
                  <div className="flex items-start gap-3">
                    <div style={{ background: st.bg }} className="h-10 w-10 rounded-2xl flex items-center justify-center shrink-0"><Icone size={18} color={st.color} /></div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-start justify-between gap-2">
                        <p className="text-sm font-semibold leading-tight">{r.titulo || `Verificação de Validade — ${r.setor}`}</p>
                        <span style={{ background: st.bg, color: st.color }} className="text-[9.5px] font-bold px-2 py-1 rounded-full shrink-0">{st.label}</span>
                      </div>
                      <p style={{ color: T.subtext }} className="text-[11px] mt-0.5">Loja {lojaNumero || "—"} · Setor {r.setor}</p>
                      <div className="flex items-center gap-3 mt-1.5">
                        <span style={{ color: T.subtext }} className="text-[10.5px] flex items-center gap-1"><ClockIcon className="w-3 h-3" /> {formatarHora(r.iniciadoEm)}–{(r.status === "concluida" || r.status === "parcial") ? formatarHora(r.finalizadoEm) : "aberto"}</span>
                        {r.usuario && <span style={{ color: T.subtext }} className="text-[10.5px] truncate">{r.usuario}{r.finalizadoPor && r.finalizadoPor !== r.usuario ? ` → ${r.finalizadoPor}` : ""}</span>}
                      </div>
                    </div>
                  </div>
                  {(r.status === "concluida" || r.status === "parcial") && (
                    <>
                      <div style={{ background: T.chipBg }} className="h-1.5 rounded-full overflow-hidden mt-3">
                        <div style={{ width: `${pctConferido}%`, background: st.color }} className="h-full rounded-full" />
                      </div>
                      <div className="flex items-center gap-2.5 mt-2.5 flex-wrap">
                        <span style={{ background: "#E6F7ED", color: "#1F9D55" }} className="text-[10px] font-bold px-2 py-0.5 rounded-full">🟢 {r.okCount ?? 0}</span>
                        <span style={{ background: "#FCF0DD", color: "#C2760C" }} className="text-[10px] font-bold px-2 py-0.5 rounded-full">🟡 {r.proximoCount ?? 0}</span>
                        <span style={{ background: RED_SOFT, color: RED_DARK }} className="text-[10px] font-bold px-2 py-0.5 rounded-full">🔴 {r.vencidoCount ?? 0}</span>
                        <span style={{ background: "#EEF0F3", color: "#4B5563" }} className="text-[10px] font-bold px-2 py-0.5 rounded-full">⚫ {r.naoEncontradoCount ?? 0}</span>
                        {r.status === "parcial" && r.totalVerificado > totalConferido && (
                          <span style={{ color: "#C2760C" }} className="text-[10px] font-bold ml-auto">{r.totalVerificado - totalConferido} sem conferir</span>
                        )}
                      </div>
                    </>
                  )}
                </div>
              </motion.button>
            );
          })}
        </div>
      )}

      {/* Detalhe da ronda: fotos dos itens + tag de conferido/não conferido */}
      <AnimatePresence>
        {rondaSelecionada && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-50 flex flex-col" style={{ background: T.bg }}>
            <div style={{ background: `linear-gradient(135deg, ${BLUE} 0%, ${BLUE_DARK} 100%)` }} className="px-4 pb-4 shrink-0 flex items-center gap-3 pt-[calc(env(safe-area-inset-top)+20px)]">
              <button onClick={() => { setRondaSelecionada(null); setItensRonda(null); }} className="h-9 w-9 rounded-full bg-white/15 flex items-center justify-center shrink-0">
                <ArrowLeft size={16} color="#fff" />
              </button>
              <div className="min-w-0">
                <h2 className="text-white font-bold text-base truncate">{rondaSelecionada.titulo || `Verificação de Validade — ${rondaSelecionada.setor}`}</h2>
                <p className="text-white/70 text-[11px]">Setor {rondaSelecionada.setor} · {formatarDataHoraExtenso(rondaSelecionada.iniciadoEm)}</p>
              </div>
            </div>
            {rondaSelecionada.status === "parcial" && isSameDay(rondaSelecionada.iniciadoEm, new Date().toISOString()) && onRetomarRonda && (
              <div className="px-4 py-3 shrink-0">
                <button onClick={() => onRetomarRonda(rondaSelecionada)} style={{ background: "#E0921C" }} className="w-full text-white text-sm font-semibold py-3 rounded-2xl flex items-center justify-center gap-2">
                  <ShieldCheck size={16} /> Continuar ronda (itens pendentes)
                </button>
              </div>
            )}
            <div className="flex-1 overflow-y-auto px-4 py-3 pb-8">
              {carregandoItens ? (
                <div className="flex justify-center py-10"><Loader2 size={22} className="animate-spin" color={BLUE} /></div>
              ) : !itensRonda || itensRonda.length === 0 ? (
                <p style={{ color: T.subtext }} className="text-xs text-center py-10">Sem detalhe de itens salvo pra essa ronda.</p>
              ) : (() => {
                const conferidos = itensRonda.filter((it) => it.statusRonda);
                const pendentes = itensRonda.filter((it) => !it.statusRonda);
                const listaFiltrada = filtroDetalhe === "conferidos" ? conferidos : filtroDetalhe === "pendentes" ? pendentes : itensRonda;
                return (
                  <>
                    <div style={{ background: T.chipBg }} className="flex rounded-2xl p-1 mb-3.5">
                      <button onClick={() => setFiltroDetalhe("conferidos")} style={filtroDetalhe === "conferidos" ? { background: T.card, color: "#1F9D55" } : { color: T.subtext }}
                        className="flex-1 text-[11px] font-semibold py-2 rounded-xl transition">Conferidos ({conferidos.length})</button>
                      <button onClick={() => setFiltroDetalhe("pendentes")} style={filtroDetalhe === "pendentes" ? { background: T.card, color: "#C2760C" } : { color: T.subtext }}
                        className="flex-1 text-[11px] font-semibold py-2 rounded-xl transition">Pendentes ({pendentes.length})</button>
                      <button onClick={() => setFiltroDetalhe("todos")} style={filtroDetalhe === "todos" ? { background: T.card, color: T.text } : { color: T.subtext }}
                        className="flex-1 text-[11px] font-semibold py-2 rounded-xl transition">Todos ({itensRonda.length})</button>
                    </div>
                    {listaFiltrada.length === 0 ? (
                      <p style={{ color: T.subtext }} className="text-xs text-center py-10">Nenhum item nessa categoria.</p>
                    ) : (
                      <div className="flex flex-col gap-2.5">
                        {listaFiltrada.map((it) => {
                          const tag = it.statusRonda ? TAG_STATUS[it.statusRonda] : null;
                          return (
                            <div key={it.id} style={{ background: T.card }} className="rounded-2xl p-3 shadow-lg shadow-black/5 flex items-center gap-3">
                              <div className="relative shrink-0">
                                <Thumb foto={it.foto} size={52} />
                                <span style={{ background: tag ? tag.bg : "#9CA3AF" }} className="absolute -bottom-1 -right-1 text-white text-[8px] font-bold px-1.5 py-0.5 rounded-full whitespace-nowrap shadow">
                                  {tag ? tag.label : "Não conferido"}
                                </span>
                              </div>
                              <div className="min-w-0 flex-1">
                                <p className="text-sm font-medium truncate">{it.nome}</p>
                                {it.validade && <p style={{ color: T.subtext }} className="text-[11px]">Validade {formatarData(it.validade)}</p>}
                                {it.acao && <p style={{ color: "#C2760C" }} className="text-[10px] font-semibold mt-0.5">Ação: {it.acao}</p>}
                                {it.conferidoPor && <p style={{ color: T.subtext }} className="text-[10px]">Conferido por {it.conferidoPor}</p>}
                                {it.barcode && <p style={{ color: T.subtext }} className="text-[10px] font-mono">{it.barcode}</p>}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </>
                );
              })()}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

// ============ Torre de Controle (itens 26, 30, 31, 32, 37) — tela pra liderança ============
// Dados agregados usados pela Torre de Controle e pela aba Relatórios (resumo geral, setores, itens)
function usarDadosGerenciais(items, historico) {
  const enriched = items.map((it) => ({ ...it, status: getStatus(it) }));
  const criticos = enriched.filter((i) => i.status.level === "expired");
  const atencao = enriched.filter((i) => i.status.level === "alert");
  const valorEmRisco = [...criticos, ...atencao].reduce((acc, i) => acc + (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0), 0);

  const previsaoAmanha = useMemo(() => {
    const entrarao = enriched.filter((i) => i.status.level !== "expired" && i.status.d - 1 <= i.diasAlerta && i.status.d - 1 >= 0 && i.status.level !== "alert");
    const valor = entrarao.reduce((acc, i) => acc + (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0), 0);
    return { qtd: entrarao.length, valor };
  }, [items]);

  const riscoPorSetor = useMemo(() => {
    const mapa = {};
    [...criticos, ...atencao].forEach((i) => { mapa[i.setor] = (mapa[i.setor] || 0) + (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0); });
    return Object.entries(mapa).sort((a, b) => b[1] - a[1]);
  }, [items]);
  const setorMaisPerigoso = riscoPorSetor[0];

  const riscoPorCorredor = useMemo(() => {
    const mapa = {};
    [...criticos, ...atencao].forEach((i) => {
      if (!i.corredor) return;
      const chave = `Corredor ${i.corredor}${i.ladoCorredor ? " · " + i.ladoCorredor : ""}`;
      if (!mapa[chave]) mapa[chave] = { valor: 0, vencidos: 0, proximos: 0 };
      mapa[chave].valor += (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0);
      if (i.status.level === "expired") mapa[chave].vencidos++; else mapa[chave].proximos++;
    });
    return Object.entries(mapa).sort((a, b) => b[1].valor - a[1].valor).slice(0, 5);
  }, [items]);

  const tendenciaPerdas = useMemo(() => {
    const agora = new Date();
    const inicioMesAtual = new Date(agora.getFullYear(), agora.getMonth(), 1).getTime();
    const inicioMesAnterior = new Date(agora.getFullYear(), agora.getMonth() - 1, 1).getTime();
    let atual = 0, anterior = 0;
    historico.forEach((h) => {
      if (!h.vencidoAntes) return;
      const t = new Date(h.dataBaixa).getTime();
      const valor = (Number(h.quantidade) || 1) * (Number(h.precoUnitario) || 0);
      if (t >= inicioMesAtual) atual += valor;
      else if (t >= inicioMesAnterior) anterior += valor;
    });
    const variacao = anterior > 0 ? Math.round(((atual - anterior) / anterior) * 100) : null;
    return { atual, anterior, variacao };
  }, [historico]);

  const reincidentes = useMemo(() => {
    const janela = Date.now() - 60 * 86400000;
    const mapa = {};
    historico.filter((h) => h.vencidoAntes && new Date(h.dataBaixa).getTime() >= janela).forEach((h) => {
      if (!mapa[h.barcode]) mapa[h.barcode] = { nome: h.nome, setor: h.setor, datas: [] };
      mapa[h.barcode].datas.push(h.dataBaixa);
    });
    return Object.values(mapa).filter((p) => p.datas.length >= 3).sort((a, b) => b.datas.length - a.datas.length).slice(0, 6);
  }, [historico]);

  const rankingResponsaveis = useMemo(() => {
    const mapa = {};
    historico.forEach((h) => { const nome = h.registradoPor || "Não identificado"; mapa[nome] = (mapa[nome] || 0) + 1; });
    return Object.entries(mapa).sort((a, b) => b[1] - a[1]).slice(0, 6);
  }, [historico]);

  // Resumo por setor (pra aba Relatórios): total de itens, críticos, atenção, valor em risco por setor
  const resumoPorSetor = useMemo(() => {
    const mapa = {};
    enriched.forEach((i) => {
      if (!mapa[i.setor]) mapa[i.setor] = { total: 0, criticos: 0, atencao: 0, ok: 0, valorEmRisco: 0 };
      mapa[i.setor].total++;
      if (i.status.level === "expired") mapa[i.setor].criticos++;
      else if (i.status.level === "alert") mapa[i.setor].atencao++;
      else mapa[i.setor].ok++;
      if (i.status.level === "expired" || i.status.level === "alert") mapa[i.setor].valorEmRisco += (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0);
    });
    return Object.entries(mapa).sort((a, b) => b[1].valorEmRisco - a[1].valorEmRisco);
  }, [items]);

  return {
    enriched, criticos, atencao, valorEmRisco, previsaoAmanha, riscoPorSetor, setorMaisPerigoso,
    riscoPorCorredor, tendenciaPerdas, reincidentes, rankingResponsaveis, resumoPorSetor,
  };
}

// Gera o relatório gerencial em PDF — usado pela Torre de Controle e pela aba Relatórios (mesmo layout)
// Relatório dedicado de itens próximos a vencer (ainda não vencidos, dentro da janela de alerta) —
// pra imprimir/mandar pro setor conferir e agir antes de virar perda de verdade.
function gerarPDFProximosAVencer(itensProximos, { usuario, lojaNumero }) {
  const BLUE_DARK_RGB = [8, 47, 94], RED_RGB = [227, 30, 36], GRAY_RGB = [107, 114, 128], LIGHT_RGB = [244, 245, 249];
  const doc = new jsPDF();
  const pageW = 210;
  let y = 0;

  doc.setFillColor(...BLUE_DARK_RGB);
  doc.rect(0, 0, pageW, 38, "F");
  doc.setFillColor(...[201, 138, 12]);
  doc.rect(0, 38, pageW, 2, "F");
  doc.setFillColor(255, 255, 255);
  doc.roundedRect(12, 7, 56, 15, 2, 2, "F");
  const LOGO_W = 50, LOGO_H = LOGO_W * (199 / 900);
  doc.addImage(CONDOR_LOGO_BASE64, "PNG", 15, 7 + (15 - LOGO_H) / 2, LOGO_W, LOGO_H);
  doc.setTextColor(255, 255, 255); doc.setFont(undefined, "bold"); doc.setFontSize(11.5);
  doc.text("Itens Próximos ao Vencimento", 74, 14);
  doc.setFont(undefined, "normal"); doc.setFontSize(9.5);
  doc.text(`Loja ${lojaNumero || "79"}`, 74, 20.5);
  doc.setFontSize(8);
  doc.text(`Gerado em ${formatarDataHoraExtenso(new Date().toISOString())} por ${usuario || "—"}`, 74, 26.5);

  y = 48;
  const valorTotal = itensProximos.reduce((acc, i) => acc + (Number(i.quantidade) || 1) * (Number(i.precoUnitario) || 0), 0);
  doc.setFillColor(...LIGHT_RGB);
  doc.roundedRect(14, y, pageW - 28, 16, 2, 2, "F");
  doc.setTextColor(...BLUE_DARK_RGB); doc.setFont(undefined, "bold"); doc.setFontSize(9);
  doc.text(`${itensProximos.length} item(ns) próximo(s) do vencimento`, 18, y + 10);
  doc.setTextColor(...RED_RGB); doc.setFont(undefined, "normal"); doc.setFontSize(8.5);
  doc.text(`Valor exposto: ${formatarMoeda(valorTotal)}`, pageW - 18, y + 10, { align: "right" });
  y += 24;

  const truncarParaCaber = (texto, larguraDisponivel) => {
    texto = String(texto);
    if (doc.getTextWidth(texto) <= larguraDisponivel) return texto;
    let cortado = texto;
    while (cortado.length > 1 && doc.getTextWidth(cortado + "…") > larguraDisponivel) cortado = cortado.slice(0, -1);
    return cortado + "…";
  };
  const larguras = [52, 34, 26, 24, 20, 26];
  const xs = []; let acc = 14; larguras.forEach((w) => { xs.push(acc); acc += w; });
  const colunas = ["PRODUTO", "SETOR", "VALIDADE", "FALTAM", "QTD.", "VALOR"];
  doc.setFillColor(235, 237, 242);
  doc.rect(14, y - 5, pageW - 28, 6, "F");
  doc.setFont(undefined, "bold"); doc.setFontSize(7.5); doc.setTextColor(...GRAY_RGB);
  colunas.forEach((c, i) => doc.text(truncarParaCaber(c, larguras[i] - 3), xs[i] + 2, y - 1));
  y += 3;
  doc.setFont(undefined, "normal"); doc.setFontSize(8); doc.setTextColor(...BLUE_DARK_RGB);
  itensProximos.forEach((item, li) => {
    if (y > 278) { doc.addPage(); y = 16; }
    if (li % 2 === 0) { doc.setFillColor(249, 249, 251); doc.rect(14, y - 4, pageW - 28, 6, "F"); }
    const valorItem = (Number(item.quantidade) || 1) * (Number(item.precoUnitario) || 0);
    const linha = [item.nome, item.setor, formatarData(item.validade), `${item.status.d}d`, item.porPeso ? `${item.quantidade}kg` : String(item.quantidade || 1), formatarMoeda(valorItem)];
    linha.forEach((val, i) => doc.text(truncarParaCaber(val, larguras[i] - 3), xs[i] + 2, y));
    y += 6.2;
  });

  doc.save(`itens-proximos-vencer-loja${lojaNumero || "79"}-${new Date().toISOString().slice(0, 10)}.pdf`);
}

async function gerarRelatorioGerencialPDF({ items, historico, usuario, showToast, criticos, atencao, valorEmRisco, tendenciaPerdas, riscoPorSetor, riscoPorCorredor, reincidentes, rankingResponsaveis, rondas, lojaNumero, secoes }) {
  const inclui = (chave) => !secoes || secoes.has(chave);
  const hoje = new Date();
  // Paleta da marca Condor: azul-marinho (identidade) + vermelho (alerta), não preto puro
  const BLUE_RGB = [11, 79, 158], BLUE_DARK_RGB = [8, 47, 94], RED_RGB = [227, 30, 36], RED_DARK_RGB = [168, 20, 25], GRAY_RGB = [107, 114, 128], LIGHT_RGB = [244, 245, 249];
  const doc = new jsPDF();
  const pageW = 210;
  let y = 0;

  // --- Cabeçalho com a logo oficial da Condor ---
  doc.setFillColor(...BLUE_DARK_RGB);
  doc.rect(0, 0, pageW, 38, "F");
  doc.setFillColor(...RED_RGB);
  doc.rect(0, 38, pageW, 2, "F");
  // Logo em cartão branco (a arte é azul/vermelho, precisa de fundo claro pra aparecer sobre o header escuro)
  doc.setFillColor(255, 255, 255);
  doc.roundedRect(12, 7, 56, 15, 2, 2, "F");
  const LOGO_W = 50, LOGO_H = LOGO_W * (199 / 900);
  doc.addImage(CONDOR_LOGO_BASE64, "PNG", 15, 7 + (15 - LOGO_H) / 2, LOGO_W, LOGO_H);
  doc.setTextColor(255, 255, 255); doc.setFont(undefined, "bold"); doc.setFontSize(11.5);
  doc.text("Relatório de Controle de Validade", 74, 14);
  doc.setFont(undefined, "normal"); doc.setFontSize(9.5);
  doc.text(`Loja ${lojaNumero || "79"}`, 74, 20.5);
  doc.setFontSize(8);
  doc.text(`Gerado em ${formatarDataHoraExtenso(hoje.toISOString())} por ${usuario || "—"}`, 74, 26.5);

  y = 48;
  doc.setTextColor(...BLUE_DARK_RGB);

  // --- KPIs em caixas ---
  const kpis = [
    { label: "Monitorados", valor: String(items.length) },
    { label: "Vencidos", valor: String(criticos.length), cor: RED_RGB },
    { label: "Em atenção", valor: String(atencao.length), cor: [201, 138, 12] },
    { label: "Valor em risco", valor: formatarMoeda(valorEmRisco), cor: RED_RGB },
  ];
  const kpiW = (pageW - 28 - 3 * 4) / 4;
  kpis.forEach((k, i) => {
    const x = 14 + i * (kpiW + 4);
    doc.setFillColor(...LIGHT_RGB);
    doc.roundedRect(x, y, kpiW, 22, 2, 2, "F");
    doc.setTextColor(...(k.cor || BLUE_DARK_RGB));
    doc.setFont(undefined, "bold"); doc.setFontSize(k.valor.length > 8 ? 10.5 : 14);
    doc.text(k.valor, x + kpiW / 2, y + 11, { align: "center" });
    doc.setTextColor(...GRAY_RGB); doc.setFont(undefined, "normal"); doc.setFontSize(7.5);
    doc.text(k.label, x + kpiW / 2, y + 18, { align: "center" });
  });
  y += 32;

  // --- Tendência de perdas ---
  doc.setFillColor(...LIGHT_RGB);
  doc.roundedRect(14, y, pageW - 28, 16, 2, 2, "F");
  doc.setTextColor(...BLUE_DARK_RGB); doc.setFont(undefined, "bold"); doc.setFontSize(9);
  doc.text(`Perdas confirmadas este mês: ${formatarMoeda(tendenciaPerdas.atual)}`, 18, y + 10);
  if (tendenciaPerdas.variacao !== null) {
    doc.setTextColor(...(tendenciaPerdas.variacao <= 0 ? [31, 157, 85] : RED_RGB));
    doc.setFont(undefined, "normal"); doc.setFontSize(8.5);
    doc.text(`${tendenciaPerdas.variacao > 0 ? "+" : ""}${tendenciaPerdas.variacao}% vs mês anterior (${formatarMoeda(tendenciaPerdas.anterior)})`, pageW - 18, y + 10, { align: "right" });
  }
  y += 24;

  const secao = (titulo) => {
    doc.setFillColor(...BLUE_DARK_RGB);
    doc.rect(14, y, pageW - 28, 7, "F");
    doc.setTextColor(255, 255, 255); doc.setFont(undefined, "bold"); doc.setFontSize(9);
    doc.text(titulo, pageW / 2, y + 5, { align: "center" });
    y += 11;
    doc.setTextColor(...BLUE_DARK_RGB);
  };
  // Corta o texto com "…" se ele não couber na largura da coluna — sem isso, nome de produto
  // comprido invadia a coluna vizinha (ex: nome grande em cima do nome do setor).
  const truncarParaCaber = (texto, larguraDisponivel) => {
    texto = String(texto);
    if (doc.getTextWidth(texto) <= larguraDisponivel) return texto;
    let cortado = texto;
    while (cortado.length > 1 && doc.getTextWidth(cortado + "…") > larguraDisponivel) cortado = cortado.slice(0, -1);
    return cortado + "…";
  };
  const tabela = (colunas, linhas, larguras) => {
    const xs = []; let acc = 14; larguras.forEach((w) => { xs.push(acc); acc += w; });
    doc.setFillColor(235, 237, 242);
    doc.rect(14, y - 5, pageW - 28, 6, "F");
    doc.setFont(undefined, "bold"); doc.setFontSize(7.5); doc.setTextColor(...GRAY_RGB);
    colunas.forEach((c, i) => doc.text(truncarParaCaber(c, larguras[i] - 3), xs[i] + 2, y - 1));
    y += 3;
    doc.setFont(undefined, "normal"); doc.setFontSize(8); doc.setTextColor(...BLUE_DARK_RGB);
    linhas.forEach((linha, li) => {
      if (y > 278) { doc.addPage(); y = 16; }
      if (li % 2 === 0) { doc.setFillColor(249, 249, 251); doc.rect(14, y - 4, pageW - 28, 6, "F"); }
      linha.forEach((val, i) => doc.text(truncarParaCaber(val, larguras[i] - 3), xs[i] + 2, y));
      y += 6.2;
    });
    y += 6;
  };

  // --- Top setores em risco ---
  if (inclui("setores") && riscoPorSetor.length > 0) {
    secao("TOP SETORES EM RISCO AGORA");
    tabela(["SETOR", "VALOR EXPOSTO"], riscoPorSetor.slice(0, 6).map(([s, v]) => [s, formatarMoeda(v)]), [126, 56]);
  }

  // --- Top corredores ---
  if (inclui("corredores") && riscoPorCorredor.length > 0) {
    secao("RISCO POR CORREDOR / LOCALIZAÇÃO");
    tabela(["LOCAL", "VENCIDOS", "VALOR"], riscoPorCorredor.map(([l, d]) => [l, String(d.vencidos), formatarMoeda(d.valor)]), [96, 40, 46]);
  }

  // --- Reincidência ---
  if (inclui("reincidentes") && reincidentes.length > 0) {
    secao("PRODUTOS REINCIDENTES (60 DIAS) — REVISAR PROCESSO DE COMPRA/REPOSIÇÃO");
    tabela(["PRODUTO", "SETOR", "Nº DE BAIXAS"], reincidentes.map((p) => [p.nome, p.setor, String(p.datas.length)]), [96, 56, 30]);
  }

  // --- Ranking de responsáveis ---
  if (inclui("responsaveis") && rankingResponsaveis.length > 0) {
    secao("REGISTROS POR RESPONSÁVEL (BAIXAS)");
    tabela(["RESPONSÁVEL", "BAIXAS REGISTRADAS"], rankingResponsaveis.map(([n, q]) => [n, String(q)]), [126, 56]);
  }

  // --- Execução de rondas (últimos 30 dias) ---
  if (inclui("rondas") && rondas && rondas.length > 0) {
    const janela30 = Date.now() - 30 * 86400000;
    const rondasRecentes = rondas.filter((r) => new Date(r.iniciadoEm).getTime() >= janela30);
    const concluidas = rondasRecentes.filter((r) => r.status === "concluida").length;
    const parciais = rondasRecentes.filter((r) => r.status === "parcial").length;
    const taxa = rondasRecentes.length ? Math.round((concluidas / rondasRecentes.length) * 100) : 0;
    secao("EXECUÇÃO DE RONDAS (ÚLTIMOS 30 DIAS)");
    tabela(
      ["MÉTRICA", "VALOR"],
      [["Rondas realizadas", String(rondasRecentes.length)], ["Concluídas", String(concluidas)], ["Parciais", String(parciais)], ["Taxa de conclusão", `${taxa}%`]],
      [126, 56]
    );
    const porSetor = {};
    rondasRecentes.forEach((r) => { porSetor[r.setor] = (porSetor[r.setor] || 0) + 1; });
    const topSetores = Object.entries(porSetor).sort((a, b) => b[1] - a[1]).slice(0, 6);
    if (topSetores.length > 0) tabela(["SETOR", "RONDAS NO PERÍODO"], topSetores.map(([s, q]) => [s, String(q)]), [126, 56]);
  }

  // --- Ações registradas nas rondas (redução de preço, remanejamento etc) ---
  if (inclui("acoesRondas")) {
    try {
      const { data: acaoRows } = await supabase.from("ronda_itens").select("acao").not("acao", "is", null).limit(1000);
      if (acaoRows && acaoRows.length > 0) {
        const mapaAcoes = {};
        acaoRows.forEach((r) => { if (r.acao) mapaAcoes[r.acao] = (mapaAcoes[r.acao] || 0) + 1; });
        const listaAcoes = Object.entries(mapaAcoes).sort((a, b) => b[1] - a[1]);
        if (listaAcoes.length > 0) {
          secao("AÇÕES REGISTRADAS NAS RONDAS");
          tabela(["AÇÃO", "QUANTIDADE"], listaAcoes.map(([a, q]) => [a, String(q)]), [126, 56]);
        }
      }
    } catch (e) { console.error("Erro ao buscar ações das rondas:", e); }
  }

  // --- Itens prioritários agora ---
  if (inclui("prioritarios")) {
    const prioritarios = items
      .map((i) => ({ item: i, p: calcularPrioridade(i, historico) }))
      .filter((x) => x.p)
      .sort((a, b) => b.p.score - a.p.score)
      .slice(0, 15);
    if (prioritarios.length > 0) {
      secao("ITENS PRIORITÁRIOS — AÇÃO RECOMENDADA");
      tabela(
        ["PRODUTO", "SETOR", "VALIDADE", "VALOR", "AÇÃO"],
        prioritarios.map(({ item, p }) => [
          (p.nivel === "urgente" ? "[URGENTE] " : "") + item.nome, item.setor, formatarData(item.validade), formatarMoeda(p.valor), p.acao,
        ]),
        [58, 30, 24, 26, 44]
      );
    }
  }

  // --- Rodapé com paginação ---
  const totalPaginas = doc.internal.getNumberOfPages();
  for (let p = 1; p <= totalPaginas; p++) {
    doc.setPage(p);
    doc.setDrawColor(230, 230, 230);
    doc.line(14, 289, pageW - 14, 289);
    doc.setFontSize(7.5); doc.setTextColor(...GRAY_RGB); doc.setFont(undefined, "normal");
    doc.text(`Condor Validade · Loja ${lojaNumero || "79"}`, 14, 293);
    doc.text(`Página ${p} de ${totalPaginas}`, pageW - 14, 293, { align: "right" });
  }

  doc.save(`condor-relatorio-gerencial-${hoje.toISOString().slice(0, 10)}.pdf`);
  showToast && showToast("Relatório gerado.", "ok");
}

// ---------- Base compartilhada pros 2 novos relatórios (Financeiro e Atividade) ----------
function criarRelatorioPDFBase(titulo, subtitulo, usuario, lojaNumero) {
  const BLUE_DARK_RGB = [8, 47, 94], RED_RGB = [227, 30, 36], GRAY_RGB = [107, 114, 128], LIGHT_RGB = [244, 245, 249];
  const doc = new jsPDF();
  const pageW = 210;
  let y = 48;
  const hoje = new Date();

  doc.setFillColor(...BLUE_DARK_RGB);
  doc.rect(0, 0, pageW, 38, "F");
  doc.setFillColor(...RED_RGB);
  doc.rect(0, 38, pageW, 2, "F");
  doc.setFillColor(255, 255, 255);
  doc.roundedRect(12, 7, 56, 15, 2, 2, "F");
  const LOGO_W = 50, LOGO_H = LOGO_W * (199 / 900);
  doc.addImage(CONDOR_LOGO_BASE64, "PNG", 15, 7 + (15 - LOGO_H) / 2, LOGO_W, LOGO_H);
  doc.setTextColor(255, 255, 255); doc.setFont(undefined, "bold"); doc.setFontSize(11.5);
  doc.text(titulo, 74, 14);
  doc.setFont(undefined, "normal"); doc.setFontSize(9.5);
  doc.text(`Loja ${lojaNumero || "79"}${subtitulo ? " · " + subtitulo : ""}`, 74, 20.5);
  doc.setFontSize(8);
  doc.text(`Gerado em ${formatarDataHoraExtenso(hoje.toISOString())} por ${usuario || "—"}`, 74, 26.5);
  doc.setTextColor(...BLUE_DARK_RGB);

  const kpisRow = (kpis) => {
    const kpiW = (pageW - 28 - (kpis.length - 1) * 4) / kpis.length;
    kpis.forEach((k, i) => {
      const x = 14 + i * (kpiW + 4);
      doc.setFillColor(...LIGHT_RGB);
      doc.roundedRect(x, y, kpiW, 22, 2, 2, "F");
      doc.setTextColor(...(k.cor || BLUE_DARK_RGB));
      doc.setFont(undefined, "bold"); doc.setFontSize(k.valor.length > 8 ? 10 : 14);
      doc.text(k.valor, x + kpiW / 2, y + 11, { align: "center" });
      doc.setTextColor(...GRAY_RGB); doc.setFont(undefined, "normal"); doc.setFontSize(7.5);
      doc.text(k.label, x + kpiW / 2, y + 18, { align: "center" });
    });
    y += 32;
  };

  const secao = (texto) => {
    if (y > 270) { doc.addPage(); y = 16; }
    doc.setFillColor(...BLUE_DARK_RGB);
    doc.rect(14, y, pageW - 28, 7, "F");
    doc.setTextColor(255, 255, 255); doc.setFont(undefined, "bold"); doc.setFontSize(9);
    doc.text(texto, 17, y + 5);
    y += 11;
    doc.setTextColor(...BLUE_DARK_RGB);
  };

  const tabela = (colunas, linhas, larguras) => {
    if (y > 265) { doc.addPage(); y = 16; }
    const xs = []; let acc = 14; larguras.forEach((w) => { xs.push(acc); acc += w; });
    doc.setFillColor(235, 237, 242);
    doc.rect(14, y - 5, pageW - 28, 6, "F");
    doc.setFont(undefined, "bold"); doc.setFontSize(7.5); doc.setTextColor(...GRAY_RGB);
    colunas.forEach((c, i) => doc.text(c, xs[i] + 2, y - 1));
    y += 3;
    doc.setFont(undefined, "normal"); doc.setFontSize(8); doc.setTextColor(...BLUE_DARK_RGB);
    if (!linhas.length) { doc.setTextColor(...GRAY_RGB); doc.text("Sem dados no período.", 16, y); y += 8; return; }
    linhas.forEach((linha, li) => {
      if (y > 278) { doc.addPage(); y = 16; }
      if (li % 2 === 0) { doc.setFillColor(249, 249, 251); doc.rect(14, y - 4, pageW - 28, 6, "F"); }
      linha.forEach((val, i) => doc.text(String(val), xs[i] + 2, y));
      y += 6.2;
    });
    y += 6;
  };

  const finalizar = (filename, showToast, msg) => {
    const totalPaginas = doc.internal.getNumberOfPages();
    for (let p = 1; p <= totalPaginas; p++) {
      doc.setPage(p);
      doc.setDrawColor(230, 230, 230);
      doc.line(14, 289, pageW - 14, 289);
      doc.setFontSize(7.5); doc.setTextColor(...GRAY_RGB); doc.setFont(undefined, "normal");
      doc.text(`Condor Validade · Loja ${lojaNumero || "79"}`, 14, 293);
      doc.text(`Página ${p} de ${totalPaginas}`, pageW - 14, 293, { align: "right" });
    }
    doc.save(filename);
    showToast && showToast(msg, "ok");
  };

  return { doc, secao, tabela, kpisRow, finalizar };
}

// ---------- Relatório 4: Financeiro (valor exposto por faixa, política de troca, top itens em risco) ----------
async function gerarRelatorioFinanceiroPDF({ usuario, showToast, lojaNumero, valorTotalMonitorado, valorEmRisco, faixasRisco, porPoliticaTroca, topRisco }) {
  const { secao, tabela, kpisRow, finalizar } = criarRelatorioPDFBase(
    "Relatório Financeiro de Validade", "Valor exposto, faixas de risco e perdas", usuario, lojaNumero
  );

  kpisRow([
    { label: "Valor monitorado", valor: formatarMoeda(valorTotalMonitorado) },
    { label: "Valor em risco", valor: formatarMoeda(valorEmRisco), cor: [227, 30, 36] },
    { label: "Itens vencidos", valor: String(faixasRisco.find((f) => f.label === "Vencidos")?.qtd || 0), cor: [227, 30, 36] },
  ]);

  secao("VALOR EXPOSTO POR FAIXA DE VENCIMENTO");
  tabela(["FAIXA", "ITENS", "VALOR"], faixasRisco.map((f) => [f.label, String(f.qtd), formatarMoeda(f.valor)]), [80, 40, 62]);

  secao("VALOR POR POLÍTICA DE TROCA");
  tabela(["POLÍTICA", "ITENS", "VALOR"], [
    ["Com troca", String(porPoliticaTroca.com_troca.qtd), formatarMoeda(porPoliticaTroca.com_troca.valor)],
    ["Sem troca", String(porPoliticaTroca.sem_troca.qtd), formatarMoeda(porPoliticaTroca.sem_troca.valor)],
  ], [80, 40, 62]);

  secao("TOP 10 ITENS COM MAIOR VALOR EM RISCO");
  tabela(["PRODUTO", "SETOR", "VALIDADE", "VALOR"], topRisco.map((i) => [i.nome, i.setor, formatarData(i.validade), formatarMoeda(i.valorRisco)]), [66, 40, 32, 44]);

  finalizar(`condor-relatorio-financeiro-${new Date().toISOString().slice(0, 10)}.pdf`, showToast, "Relatório financeiro gerado.");
}

// ---------- Relatório 5: Atividade da equipe (auditoria detalhada + rondas) ----------
async function gerarRelatorioAtividadePDF({ usuario, showToast, lojaNumero, porUsuarioAuditoria, porTipoAcao, rondasResumo }) {
  const { secao, tabela, kpisRow, finalizar } = criarRelatorioPDFBase(
    "Relatório de Atividade da Equipe", "Ações registradas e rondas de validade", usuario, lojaNumero
  );

  kpisRow([
    { label: "Ações registradas", valor: String(porUsuarioAuditoria.reduce((a, [, q]) => a + q, 0)) },
    { label: "Rondas concluídas", valor: String(rondasResumo.concluidas) },
    { label: "Rondas parciais", valor: String(rondasResumo.parciais) },
  ]);

  secao("AÇÕES POR RESPONSÁVEL");
  tabela(["RESPONSÁVEL", "AÇÕES"], porUsuarioAuditoria.map(([n, q]) => [n, String(q)]), [126, 56]);

  secao("AÇÕES POR TIPO");
  tabela(["TIPO DE AÇÃO", "QTD"], porTipoAcao.map(([t, q]) => [t, String(q)]), [126, 56]);

  secao("RONDAS POR SETOR");
  tabela(["SETOR", "CONCLUÍDAS", "PARCIAIS"], rondasResumo.porSetor.map(([s, d]) => [s, String(d.concluidas), String(d.parciais)]), [86, 48, 48]);

  finalizar(`condor-relatorio-atividade-${new Date().toISOString().slice(0, 10)}.pdf`, showToast, "Relatório de atividade gerado.");
}

// ============ Painel da Rede (item 1) — visão corporativa somando todas as lojas ============
// Pressupõe uma tabela compartilhada "resumo_lojas_rede" (ver supaEnviarResumoRede/supaFetchResumoRede)
// alimentada por cada loja periodicamente. Visível só pra quem tem cargo de nível corporativo (ehCorporativo).
function RedeView({ T, showToast }) {
  const [lojas, setLojas] = useState(null); // null = carregando
  const [ordenarPor, setOrdenarPor] = useState("valorEmRisco"); // valorEmRisco | perdaMes | rondasPendentesHoje

  async function carregar() {
    const dados = await supaFetchResumoRede();
    setLojas(dados);
  }
  useEffect(() => { carregar(); }, []);

  const lojasOrdenadas = useMemo(() => {
    if (!lojas) return [];
    return [...lojas].sort((a, b) => (b[ordenarPor] || 0) - (a[ordenarPor] || 0));
  }, [lojas, ordenarPor]);

  const totais = useMemo(() => {
    if (!lojas) return null;
    return lojas.reduce((acc, l) => ({
      valorEmRisco: acc.valorEmRisco + l.valorEmRisco, perdaMes: acc.perdaMes + l.perdaMes,
      criticos: acc.criticos + l.criticos, atencao: acc.atencao + l.atencao,
      rondasPendentesHoje: acc.rondasPendentesHoje + l.rondasPendentesHoje,
    }), { valorEmRisco: 0, perdaMes: 0, criticos: 0, atencao: 0, rondasPendentesHoje: 0 });
  }, [lojas]);

  const lojasDesatualizadas = useMemo(() => (lojas || []).filter((l) => Date.now() - new Date(l.atualizadoEm).getTime() > 6 * 3600000), [lojas]);

  return (
    <div className="px-4 pt-4 pb-4">
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}
        style={{ background: `linear-gradient(160deg, #6D4FC2 0%, #4B2E9E 75%)` }} className="rounded-[28px] p-4 shadow-lg shadow-black/5 mb-4">
        <p className="text-white/70 text-[10px] font-bold uppercase tracking-wide mb-3 flex items-center gap-1.5">
          <Building2 size={14} /> Painel da Rede · {lojas ? `${lojas.length} loja(s) reportando` : "carregando…"}
        </p>
        {totais && (
          <div className="grid grid-cols-2 gap-2">
            <div className="bg-white/10 rounded-2xl px-3 py-3">
              <p className="text-white text-lg font-extrabold leading-none">{formatarMoeda(totais.valorEmRisco)}</p>
              <p className="text-white/70 text-[9.5px] mt-1">Valor em risco (rede)</p>
            </div>
            <div className="bg-white/10 rounded-2xl px-3 py-3">
              <p className="text-white text-lg font-extrabold leading-none">{formatarMoeda(totais.perdaMes)}</p>
              <p className="text-white/70 text-[9.5px] mt-1">Perda confirmada no mês</p>
            </div>
            <div className="bg-white/10 rounded-2xl px-3 py-3">
              <p className="text-white text-lg font-extrabold leading-none">{totais.criticos + totais.atencao}</p>
              <p className="text-white/70 text-[9.5px] mt-1">Produtos críticos/atenção</p>
            </div>
            <div className="bg-white/10 rounded-2xl px-3 py-3">
              <p className="text-white text-lg font-extrabold leading-none">{totais.rondasPendentesHoje}</p>
              <p className="text-white/70 text-[9.5px] mt-1">Rondas pendentes hoje</p>
            </div>
          </div>
        )}
      </motion.div>

      {lojasDesatualizadas.length > 0 && (
        <div style={{ background: "#FEF3E0", color: "#C98A0C" }} className="rounded-2xl px-3.5 py-2.5 mb-4 text-[11px] font-medium flex items-start gap-2">
          <AlertTriangle size={14} className="mt-0.5 shrink-0" />
          <span>{lojasDesatualizadas.length} loja(s) sem enviar dados há mais de 6h — pode ser app fechado ou sem internet: {lojasDesatualizadas.map((l) => l.lojaNome || `Loja ${l.lojaNumero}`).join(", ")}.</span>
        </div>
      )}

      <div style={{ background: T.chipBg }} className="flex rounded-2xl p-1 mb-4">
        {[["valorEmRisco", "Valor em risco"], ["perdaMes", "Perda no mês"], ["rondasPendentesHoje", "Rondas pendentes"]].map(([id, label]) => (
          <button key={id} onClick={() => setOrdenarPor(id)} style={ordenarPor === id ? { background: T.card, color: T.text } : { color: T.subtext }}
            className="flex-1 text-[10.5px] font-semibold py-2 rounded-xl transition">
            {label}
          </button>
        ))}
      </div>

      {lojas === null ? (
        <div className="text-center py-14"><Loader2 size={24} className="animate-spin mx-auto" color={T.subtext} /></div>
      ) : lojas.length === 0 ? (
        <div className="text-center py-14 px-6">
          <div style={{ background: "#EDE7FA" }} className="h-16 w-16 rounded-2xl mx-auto flex items-center justify-center mb-3"><Building2 className="w-6 h-6" style={{ color: "#6D4FC2" }} /></div>
          <p className="font-semibold text-sm">Nenhuma loja reportando ainda</p>
          <p style={{ color: T.subtext }} className="text-xs mt-1">Assim que as lojas abrirem o app com a tabela "resumo_lojas_rede" configurada, elas aparecem aqui.</p>
        </div>
      ) : (
        <div className="flex flex-col gap-2.5">
          {lojasOrdenadas.map((l, i) => (
            <div key={l.lojaNumero} style={{ background: T.card }} className="rounded-2xl p-3.5 shadow-lg shadow-black/5">
              <div className="flex items-center justify-between mb-2">
                <p className="text-sm font-bold">{i + 1}. {l.lojaNome || `Loja ${l.lojaNumero}`}</p>
                <span style={{ color: T.subtext }} className="text-[9.5px]">{tempoDesde(l.atualizadoEm)}</span>
              </div>
              <div className="grid grid-cols-3 gap-2">
                <div>
                  <p style={{ color: RED_DARK }} className="text-sm font-extrabold">{formatarMoeda(l.valorEmRisco)}</p>
                  <p style={{ color: T.subtext }} className="text-[9px]">Em risco</p>
                </div>
                <div>
                  <p className="text-sm font-extrabold">{formatarMoeda(l.perdaMes)}</p>
                  <p style={{ color: T.subtext }} className="text-[9px]">Perda no mês</p>
                </div>
                <div>
                  <p style={{ color: l.rondasPendentesHoje > 0 ? "#C98A0C" : "#1F9D55" }} className="text-sm font-extrabold">{l.rondasPendentesHoje}</p>
                  <p style={{ color: T.subtext }} className="text-[9px]">Rondas pendentes</p>
                </div>
              </div>
              {l.setoresSemRondaHoje?.length > 0 && (
                <p style={{ color: T.subtext, borderColor: T.border }} className="text-[10px] mt-2 pt-2 border-t">
                  Sem ronda hoje: {l.setoresSemRondaHoje.join(", ")}
                </p>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

