            <button onClick={() => exportarFinanceiro("xlsx")} style={{ background: T.chipBg, color: T.text }} className="text-[11px] font-medium px-2.5 py-1.5 rounded-full flex items-center gap-1"><FileSpreadsheet size={12} /> XLSX</button>
